<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { post, session } from '../api'; const router=useRouter(), username=ref('admin'), password=ref('admin'), error=ref(''), loading=ref(false); async function login(){error.value='';loading.value=true;try{const r=await post<{token:string;user:{mustChangePassword:boolean}}>('/auth/login',{username:username.value,password:password.value});session.token=r.token;router.push(r.user.mustChangePassword?'/account/change-initial-password':'/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script>
<template><div class="login"><section class="login-hero"><div class="login-brand">PM.</div><div class="login-copy"><h1>公司项目<br>一眼看清。</h1><div class="login-accent"/><div class="login-facts"><span>项目</span><span>风险</span><span>经营</span></div></div></section><section class="login-form-area"><form class="login-form" @submit.prevent="login"><h1>欢迎回来</h1><p class="subtitle">登录项目经营系统</p><div class="login-accent"/><div class="field-group"><label>用户名</label><input v-model="username" class="input" autocomplete="username" /></div><div class="field-group"><label>密码</label><input v-model="password" type="password" class="input" autocomplete="current-password" /></div><p v-if="error" class="error">{{ error }}</p><button class="button primary" :disabled="loading">{{ loading?'登录中…':'登录 →' }}</button><p class="subtitle" style="font-size:12px;margin-top:20px">初始账号：admin / admin<br>首次登录必须修改密码</p></form></section></div></template>
